  const sig = esc ? ZD.state.notifications.filter(n => n.items.some(i => i.taskId === esc.id)).map(n => n.kind).join(',') : '';
  const fresh = ZD.createFreeTask({ label: 'сверить реестр', assignee: 'E3', controller: 'E4', author: 'E4', dueDate: '2026-09-01' });
  ZD.runPoll();
